import csv,itertools
from pymatgen.io.vasp import Poscar
from pymatgen.analysis.structure_matcher import StructureMatcher
R={r['candidate_id']:Poscar.from_str(r['poscar']).structure for r in csv.DictReader(open('nlo_pool.csv'))}
for ids in [('c050','c051','c052'),('c024','c025','c026','c027','c028','c029'),('c040','c041','c042','c043','c044','c045'),('c076','c077','c078'),('c039','c063','c086'),('c084','c085')]:
 print(ids)
 for a,b in itertools.combinations(ids,2):
  m=StructureMatcher(ltol=.2,stol=.3,angle_tol=5,scale=True,attempt_supercell=True)
  try: print(a,b,m.fit(R[a],R[b]),m.get_rms_dist(R[a],R[b]))
  except Exception as e: print(a,b,type(e).__name__)
PY

