import csv,warnings,numpy as np
from pymatgen.io.vasp import Poscar
from pymatgen.analysis.local_env import CrystalNN
warnings.filterwarnings('ignore'); cnn=CrystalNN(weighted_cn=True)
ids={'c020','c038','c047','c048','c049','c056','c060','c064','c065','c066','c069','c070','c071','c072','c073','c074','c079','c080','c082','c089','c092','c093'}
for r in csv.DictReader(open('nlo_pool.csv')):
 if r['candidate_id'] not in ids: continue
 s=Poscar.from_str(r['poscar']).structure
 by={}
 for i,x in enumerate(s): by.setdefault(x.specie.symbol,[]).append(cnn.get_cn(s,i,use_weights=True))
 print(r['candidate_id'],r['formula'],','.join(f'{e}:{np.mean(v):.1f}' for e,v in by.items()))
